{
  "title": "Historia de Usuario (HU) de la reserva de ejemplares en la Biblioteca Municipal de Villaficticia",
  "role": "Persona socia de la Biblioteca",
  "action": "Reservar un ejemplar desde la web para recogerlo en el mostrador",
  "benefit": "Acceder a un ejemplar de libro o material en préstamo en el mostrador, cumpliendo con las condiciones establecidas en el Reglamento de reservas.",
  "description": "La persona socia quiere reservar un ejemplar de la Biblioteca Municipal de Villaficticia para recogerlo en el mostrador. El proceso comienza mediante la solicitud en la web, donde debe cumplir con las reglas de reservas establecidas, como el carné vigente, el número máximo de reservas activas y la gestión de las reservas no recogidas.",
  "business_goal": "Poner en marcha el proceso de reserva de ejemplares mediante la web, garantizando que se respeten las reglas de reservas, las limitaciones de número de ejemplares y las condiciones de la cola de reservas.",
  "scope_includes": [
    "Solicitud de reserva en la web",
    "Verificación del carné vigente y sanción activa",
    "Asignación de ejemplar según la cola de reservas",
    "Bloqueo de 48 horas para la persona socia que encabeza la cola",
    "Notificación de la reserva caducada a la persona socia"
  ],
  "scope_excludes": [
    "Renovación de préstamos que no estén dentro de la cola de reservas",
    "Reservas en títulos de los que ya tenga un ejemplar en préstamo",
    "Reservas de obras de referencia",
    "Reservas de personas con carné infantil sin límites de 4 ejemplares"
  ],
  "acceptance_criteria": [
    {
      "id": "CA-01",
      "title": "Solicitud de reserva",
      "given": ["La persona socia accede a la web de la Biblioteca y selecciona el título de libro o material que quiere reservar.", "La persona socia selecciona la opción de reservar en el mostrador."],
      "when": ["La persona socia accede a la web y selecciona el título de libro o material que quiere reservar.", "La persona socia selecciona la opción de reservar en el mostrador."],
      "then": ["Se muestra el estado de la reserva: 'Pendiente' y se inicia la cola de reservas."]
    },
    {
      "id": "CA-02",
      "title": "Verificación de requisitos",
      "given": ["La persona socia verifica que su carné esté vigente y no haya sanción activa que impida la reserva.", "La persona socia proporciona el número de reservas activas que tiene."],
      "when": ["La persona socia verifica sus requisitos.", "La persona socia proporciona su número de reservas activas."],
      "then": ["Se confirma que la reserva es válida y se le asigna el primer ejemplar disponible en la sede de recogida."]
    },
    {
      "id": "CA-03",
      "title": "Bloqueo de 48 horas",
      "given": ["La persona socia recoge el ejemplar en el mostrador dentro de 48 horas.", "La persona socia no recoge el ejemplar dentro de 48 horas."],
      "when": ["La persona socia recoge el ejemplar en el mostrador dentro de 48 horas.", "La persona socia no recoge el ejemplar dentro de 48 horas."],
      "then": ["Se bloquea la reserva por 48 horas y se le notifica a la persona socia."]
    },
    {
      "id": "CA-04",
      "title": "Renovación de reserva",
      "given": ["La persona socia cancela la reserva antes de recogerla.", "La persona socia no cancela la reserva y el ejemplar no se recoge dentro de 48 horas."],
      "when": ["La persona socia cancela la reserva antes de recogerla.", "La persona socia no cancela la reserva y el ejemplar no se recoge dentro de 48 horas."],
      "then": ["Se libera la reserva y se reanuda el proceso de cola de reservas."]
    }
  ],
  "business_rules": [
    {
      "id": "RN-RES-01",
      "description": "Solo pueden reservar las personas socias con carné vigente y sin sanción activa que impida reservar."
    },
    {
      "id": "RN-RES-02",
      "description": "Cada persona socia puede tener un máximo de 3 reservas activas."
    },
    {
      "id": "RN-RES-03",
      "description": "La reserva se hace sobre un título y una sede de recogida. El sistema asigna el primer ejemplar de ese título que quede libre y lo traslada a la sede de recogida si es necesario."
    },
    {
      "id": "RN-RES-04",
      "description": "Las reservas de un mismo título se atienden por estricto orden de llegada (cola de reservas)."
    },
    {
      "id": "RN-RES-05",
      "description": "Cuando el ejemplar queda disponible en la sede de recogida, se bloquea durante 48 horas para la persona socia que encabeza la cola, y se le notifica."
    },
    {
      "id": "RN-RES-06",
      "description": "Si el ejemplar no se recoge en esas 48 horas, la reserva caduca, el ejemplar pasa a la siguiente persona de la cola y la reserva cuenta como «no recogida» a efectos de RN-SAN-04."
    },
    {
      "id": "RN-RES-07",
      "description": "La persona socia puede cancelar una reserva en cualquier momento antes de recogerla, sin penalización."
    },
    {
      "id": "RN-RES-08",
      "description": "Mientras exista una reserva pendiente sobre un título, ningún préstamo de ese título puede renovarse."
    },
    {
      "id": "RN-RES-09",
      "description": "No se pueden reservar obras de referencia ni títulos de los que la persona socia ya tenga un ejemplar en préstamo."
    },
    {
      "id": "RN-RES-10",
      "description": "Las personas con carné infantil pueden reservar solo títulos de la colección infantil y juvenil, con el mismo máximo de 3 reservas activas."
    }
  ],
  "assumptions": [
    "La persona socia conoce las reglas de reservas y el número máximo de ejemplares en préstamo.",
    "La persona socia tiene acceso a la web de la Biblioteca para solicitar reservas.",
    "La persona socia tiene un carné vigente y no está sancionada."
  ],
  "constraints": [
    "No se pueden realizar reservas de obras de referencia ni de títulos ya en préstamo.",
    "Las reservas deben cumplir con las reglas de número de ejemplares y de cola de reservas."
  ],
  "dependencies": [
    "El sistema de reservas debe poder gestionar la cola de reservas y la entrega de ejemplares.",
    "El sistema debe poder notificar a la persona socia de la caducidad de la reserva."
  ],
  "alternate_flows": [
    "Si la persona socia no recoge el ejemplar dentro de 48 horas, se bloquea y se le notifica, pero si no recoge dentro de los 48 horas, se da por caduca y se le da al siguiente en la cola.",
    "Si la persona socia cancela la reserva antes de recogerla, se libera el proceso."
  ],
  "exceptions": [
    "Las reservas de obras de referencia y los títulos ya en préstamo no están contempladas.",
    "La alternativa B de la acta DOC-20 permite nuevas reservas con limite de 3 no recogidas en 90 días."
  ],
  "related_features": [
    "Los sistemas de gestión de préstamos y reservas.",
    "Los sistemas de notificación y bloqueo de reservas caduca."
  ],
  "priority": "Should",
  "open_questions": [
    "¿Cómo se gestionará el número máximo de reservas activas en la web?",
    "¿Cómo se comunicará la cantidad de reservas no recogidas acumuladas a la persona socia?",
    "¿Cómo se garantizará que el sistema no permita renovaciones de préstamos que no estén dentro de la cola de reservas?"
  ]
}

